import{_t as e,it as t,n,rt as r}from"./chunks/framework.BzA9dy5I.js";var i=JSON.parse(`{"title":"Tu primer flujo","description":"","frontmatter":{},"headers":[],"relativePath":"guia/primeros-pasos.md","filePath":"guia/primeros-pasos.md"}`),a={name:`guia/primeros-pasos.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="tu-primer-flujo" tabindex="-1">Tu primer flujo <a class="header-anchor" href="#tu-primer-flujo" aria-label="Permalink to “Tu primer flujo”">​</a></h1><p>Necesitas una herramienta de IA compatible y Hyperion conectado a ella. La conexión se hace una vez; tus siguientes peticiones se escriben en el chat.</p><h2 id="_1-abre-hyperion" tabindex="-1">1. Abre Hyperion <a class="header-anchor" href="#_1-abre-hyperion" aria-label="Permalink to “1. Abre Hyperion”">​</a></h2><p><a href="https://github.com/0vas/hiperion/releases/tag/v0.4.0-preview.1" target="_blank" rel="noreferrer">Descargar Hyperion Desktop</a>.</p><p>Elige el instalador para tu equipo: <code>.dmg</code> para Mac (Apple Silicon o Intel) y <code>.exe</code> para Windows x64. Ábrelo e instala la aplicación. En Mac, mueve Hyperion a <strong>Aplicaciones</strong> antes de conectar tu IA. Esta preview aún no está firmada ni notarizada: el sistema puede mostrar un aviso de editor no verificado.</p><h2 id="_2-conecta-tu-ia" tabindex="-1">2. Conecta tu IA <a class="header-anchor" href="#_2-conecta-tu-ia" aria-label="Permalink to “2. Conecta tu IA”">​</a></h2><p>Al abrir Hyperion, elige <strong>Codex</strong>, <strong>Cursor</strong>, <strong>Claude Desktop</strong> o <strong>Claude Code</strong> en el asistente. También puedes acceder desde <strong>Hyperion → Conectar con mi IA</strong>.</p><p>El asistente prepara la conexión local. Reinicia tu herramienta de IA y abre un chat nuevo para que cargue la integración. No necesitas Node.js ni editar archivos de configuración para este recorrido con Desktop.</p><h2 id="_3-pide-lo-que-necesitas" tabindex="-1">3. Pide lo que necesitas <a class="header-anchor" href="#_3-pide-lo-que-necesitas" aria-label="Permalink to “3. Pide lo que necesitas”">​</a></h2><p>Por ejemplo, desde un chat nuevo:</p><blockquote><p>Usa Hyperion para preparar una guía de bienvenida a mi proyecto.</p></blockquote><p>No hace falta explicar cómo crear el flujo. El agente debe preparar el plan, compartir su enlace y pedir solo la información que falta. Un chat vacío puede empezar con esa petición; la conexión debe estar instalada.</p><p>También puedes indicar dónde verlo:</p><blockquote><p>Usa Hyperion en una ventana de escritorio para organizar mi actividad.</p></blockquote><p>O pedir verlo junto al chat. La disponibilidad de una vista dividida depende de tu herramienta; el enlace abre el mismo flujo en el navegador.</p><h2 id="_4-participa-en-el-canvas" tabindex="-1">4. Participa en el canvas <a class="header-anchor" href="#_4-participa-en-el-canvas" aria-label="Permalink to “4. Participa en el canvas”">​</a></h2><p>Abre la tarea marcada <strong>Tu turno</strong>, responde y guarda. Las opciones conocidas aparecen como desplegables en los planes que las declaran; las preguntas abiertas admiten texto.</p><p>Si el agente sigue esperando tu respuesta, puede retomar el trabajo en ese mismo turno. Si el chat ya terminó, pulsa <strong>Copiar continuación</strong> y envía ese mensaje en el chat. La decisión ya quedó guardada: no tienes que escribirla otra vez.</p><h2 id="comprueba-tu-primera-prueba" tabindex="-1">Comprueba tu primera prueba <a class="header-anchor" href="#comprueba-tu-primera-prueba" aria-label="Permalink to “Comprueba tu primera prueba”">​</a></h2><ul><li>El flujo refleja tu petición y muestra el responsable de cada tarea.</li><li>Los datos que introduces aparecen en I/O y llegan a las tareas siguientes.</li><li>El borrador y sus avances reales se registran en el flujo.</li><li>Puedes revisar el resultado y volver al chat para pedir cambios.</li></ul><p>Preparar una guía no implica publicarla. La integración debe respetar el alcance de tu petición.</p><p><a href="./usar-el-flujo.html">Aprende a usar el canvas</a> o consulta <a href="./integraciones.html">problemas de conexión</a>.</p>`,22)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};